{"code":"def transform(grid):
    out=[r[:] for r in grid]
    # locate full horizontal separator of 5s
    sep=None
    for i,row in enumerate(grid):
        if row and all(x==5 for x in row):
            sep=i; break
    if sep is None: return out
    # source is the next nonempty row below separator
    src=None
    for i in range(sep+1,len(grid)):
        if any(x!=0 for x in grid[i]):
            src=i; break
    if src is None or sep==0: return out
    from collections import Counter
    cnt=Counter(grid[src])
    for j,x in enumerate(grid[src]):
        if x!=0 and cnt[x]==1:
            out[sep-1][j]=x
    return out"}

